<template><div class="grid gap-2"><div class="grid min-h-36 place-items-center rounded-md border border-dashed border-adm-line bg-adm-surface-2 p-4 text-center" :class="dragging?'ring-2 ring-adm-focus':''" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop"><img v-if="preview || (existing && !hideExisting)" :src="preview || existing" alt="Image preview" class="mb-3 max-h-40 max-w-full rounded object-contain"><p class="text-sm text-adm-ink-muted">Drop an image or <label class="cursor-pointer font-semibold text-adm-accent underline">browse<input class="sr-only" type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="choose"></label></p><p class="mt-1 text-xs text-adm-ink-muted">JPG, PNG, WebP or GIF · up to 5 MB</p></div><p v-if="error" class="text-sm text-adm-danger-ink" role="alert">{{ error }}</p><button v-if="preview || (existing && !hideExisting)" type="button" class="justify-self-start text-sm text-adm-danger-ink underline" @click="clear">Remove image</button><p v-if="hideExisting && existing && !preview" class="text-xs text-adm-warning-ink">Current image will be removed when you save.</p></div></template>
<script setup lang="ts">import { ref, watch } from 'vue';const props=defineProps<{existing?:string}>();const emit=defineEmits<{ 'update:file':[file:File|null];'remove-existing':[remove:boolean] }>();const preview=ref('');const error=ref('');const dragging=ref(false);const hideExisting=ref(false);watch(()=>props.existing,()=>{hideExisting.value=false});function apply(file?:File){error.value='';if(!file)return;if(!file.type.startsWith('image/')){error.value='Choose a valid image file.';return}if(file.size>5*1024*1024){error.value='Images must be 5 MB or smaller.';return}emit('update:file',file);emit('remove-existing',false);hideExisting.value=false;preview.value=URL.createObjectURL(file)}function choose(event:Event){apply((event.target as HTMLInputElement).files?.[0])}function drop(event:DragEvent){dragging.value=false;apply(event.dataTransfer?.files[0])}function clear(){preview.value='';emit('update:file',null);hideExisting.value=Boolean(props.existing);emit('remove-existing',hideExisting.value)}</script>
